import type { FindOptions } from '../../collections/operations/local/find.js'
import type { FindGlobalVersionsArgs } from '../../database/types.js'
import type { PayloadRequest, PopulateType, SelectType } from '../../types/index.js'
import type { TypeWithVersion } from '../../versions/types.js'
import type { SanitizedGlobalConfig } from '../config/types.js'

import { executeAccess } from '../../auth/executeAccess.js'
import { combineQueries } from '../../database/combineQueries.js'
import { sanitizeWhereQuery } from '../../database/sanitizeWhereQuery.js'
import { Forbidden, NotFound } from '../../errors/index.js'
import { afterRead } from '../../fields/hooks/afterRead/index.js'
import { deepCopyObjectSimple } from '../../utilities/deepCopyObject.js'
import { hasVersionsEnabled } from '../../utilities/getVersionsConfig.js'
import { resolveSelect } from '../../utilities/resolveSelect.js'
import { sanitizeSelect } from '../../utilities/sanitizeSelect.js'
import { buildVersionGlobalFields } from '../../versions/buildGlobalFields.js'

export type Arguments = {
  currentDepth?: number
  depth?: number
  disableErrors?: boolean
  globalConfig: SanitizedGlobalConfig
  id: number | string
  overrideAccess?: boolean
  populate?: PopulateType
  req: PayloadRequest
  showHiddenFields?: boolean
} & Pick<FindOptions<string, SelectType>, 'select'>

export const findVersionByIDOperation = async <T extends TypeWithVersion<T> = any>(
  args: Arguments,
): Promise<T> => {
  const {
    id,
    currentDepth,
    depth,
    disableErrors,
    globalConfig,
    overrideAccess,
    populate,
    req: { fallbackLocale, locale, payload },
    req,
    select: incomingSelect,
    showHiddenFields,
  } = args

  if (!hasVersionsEnabled(globalConfig)) {
    if (disableErrors) {
      return null!
    }

    throw new NotFound(req.t)
  }

  // /////////////////////////////////////
  // Access
  // /////////////////////////////////////

  const accessResults = !overrideAccess
    ? await executeAccess(
        { id, slug: globalConfig.slug, disableErrors, req },
        globalConfig.access.readVersions,
      )
    : true

  // If errors are disabled, and access returns false, return null
  if (accessResults === false) {
    return null!
  }

  const isValidID =
    (typeof id === 'string' && id.length > 0) || (typeof id === 'number' && Number.isFinite(id))

  if (!isValidID) {
    throw new NotFound(req.t)
  }

  const hasWhereAccess = typeof accessResults === 'object'

  const versionFields = buildVersionGlobalFields(payload.config, globalConfig, true)
  const select = sanitizeSelect({
    fields: versionFields,
    select: resolveSelect({
      config: globalConfig.select,
      operation: 'read',
      req,
      select: incomingSelect,
    }),
    versions: true,
  })

  const where = combineQueries({ id: { equals: id } }, accessResults)

  sanitizeWhereQuery({ fields: versionFields, payload, where })

  const findGlobalVersionsArgs: FindGlobalVersionsArgs = {
    global: globalConfig.slug,
    limit: 1,
    locale: locale!,
    req,
    select,
    where,
  }

  // /////////////////////////////////////
  // Find by ID
  // /////////////////////////////////////

  const { docs: results } = await payload.db.findGlobalVersions(findGlobalVersionsArgs)
  if (!results || results?.length === 0) {
    if (!disableErrors) {
      if (!hasWhereAccess) {
        throw new NotFound(req.t)
      }
      if (hasWhereAccess) {
        throw new Forbidden(req.t)
      }
    }

    return null!
  }

  // Clone the result - it may have come back memoized
  let result: any = deepCopyObjectSimple(results[0])

  if (!result.version) {
    result.version = {}
  }

  // Patch globalType onto version doc
  result.version.globalType = globalConfig.slug

  // /////////////////////////////////////
  // beforeRead - Collection
  // /////////////////////////////////////

  if (globalConfig.hooks?.beforeRead?.length) {
    for (const hook of globalConfig.hooks.beforeRead) {
      result =
        (await hook({
          context: req.context,
          doc: result.version,
          global: globalConfig,
          overrideAccess,
          req,
        })) || result.version
    }
  }

  // /////////////////////////////////////
  // afterRead - Fields
  // /////////////////////////////////////

  result.version = await afterRead({
    collection: null,
    context: req.context,
    currentDepth,
    depth: depth!,
    doc: result.version,
    draft: undefined!,
    fallbackLocale: fallbackLocale!,
    global: globalConfig,
    locale: locale!,
    overrideAccess: overrideAccess!,
    populate,
    req,
    select: typeof select?.version === 'object' ? select.version : undefined,
    showHiddenFields: showHiddenFields!,
  })

  // /////////////////////////////////////
  // afterRead - Global
  // /////////////////////////////////////

  if (globalConfig.hooks?.afterRead?.length) {
    for (const hook of globalConfig.hooks.afterRead) {
      result.version =
        (await hook({
          context: req.context,
          doc: result.version,
          global: globalConfig,
          overrideAccess,
          query: findGlobalVersionsArgs.where,
          req,
        })) || result.version
    }
  }

  return result
}
